import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Services.css";

function Services() {
  const [selectedService, setSelectedService] = useState(null);
  const [services, setServices] = useState([]); // fetched services
  const navigate = useNavigate();

  // Fetch services from backend
  const fetchServices = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/services");
      const data = await response.json();
      setServices(data);
    } catch (error) {
      console.error("Error fetching services:", error);
    }
  };

  useEffect(() => {
    fetchServices();
  }, []);

  const handleBookNow = () => {
    setSelectedService(null); // close modal
    navigate("/contact"); // go to contact page
  };

  return (
    <div className="services">
      <h2>Our Services</h2>
      <div className="service-cards">
        {services.map((service) => (
          <div className="card" key={service._id}>
            <strong>{service.serviceName}</strong>
            {service.imageURL && (
              <div>
                <img 
                  src={service.imageURL} 
                  alt={service.serviceName} 
                  style={{ width: "100%", marginTop: "10px", borderRadius: "5px" }}
                />
              </div>
            )}
            <br />
            <button
              style={{ marginTop: "10px", padding: "5px 10px", cursor: "pointer" }}
              onClick={() => setSelectedService(service)}
            >
              View Details
            </button>
          </div>
        ))}
      </div>

      {/* Modal */}
      {selectedService && (
        <div className="modal-overlay" onClick={() => setSelectedService(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>{selectedService.serviceName}</h3>
            <pre>
Documents Required: {selectedService.documents}
Price: {selectedService.price}
Duration: {selectedService.duration}
Description: {selectedService.description}
            </pre>
            <div style={{ display: "flex", justifyContent: "space-between", marginTop: "15px" }}>
              <button onClick={() => setSelectedService(null)}>Close</button>
              <button onClick={handleBookNow} style={{ backgroundColor: "#28a745", color: "white" }}>
                Book Now
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Services;
